mapper.select:
SELECT * FROM admin_audit_record WHERE kind=#{q.kind} AND sequence <= #{high}
AND recorded_at >= #{q.after} AND recorded_at < #{q.before}
AND target_person=#{q.person}
AND target_user=#{q.user}
AND source=#{q.source}
AND actor_user=#{q.actorUser}
AND operation=#{q.operation}
AND target_type=#{q.targetType}
AND target_id=#{q.targetId}
AND result=#{q.result}
AND (recorded_at < #{time} OR (recorded_at=#{time} AND id < #{last}))
ORDER BY recorded_at DESC,id DESC LIMIT #{q.size}
